import json
from pathlib import Path
import sys

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))


def run():
    from checkout import checkout

    try:
        total = checkout(1234)
    except TypeError as exc:
        if str(exc) != "'int' object is not subscriptable":
            raise
        return "reproduced", "checkout(1234) raises TypeError instead of returning 1234", 1
    if total != 1234:
        return "reproduced", f"checkout(1234) returned {total!r} instead of 1234", 1
    return "passed", "checkout(1234) returns 1234", 0


try:
    outcome, reason, code = run()
except Exception as exc:
    outcome, reason, code = "error", f"{type(exc).__name__}: {exc}", 2
print("NEIN_PROBE_RESULT " + json.dumps({
    "check": "checkout-quote-contract",
    "outcome": outcome,
    "reason": reason,
}))
sys.exit(code)
